import{_ as o,a as s,c as n,ac as l}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · 全册短语与句型 · 第75–96课","description":"按课次汇总短语用法与原创句型，链接对应课时。","frontmatter":{"title":"第二册：实践与进步 · 全册短语与句型 · 第75–96课","description":"按课次汇总短语用法与原创句型，链接对应课时。","splitFrom":"life/english/new-concept/book-2/phrases.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 全册短语与句型","summary":"按课次汇总短语用法与原创句型，链接对应课时。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 全册短语与句型 · 第49–74课","link":"/life/english/new-concept/book-2/phrases-part-03"},"next":{"text":"第二册：实践与进步 · 全册易错点","link":"/life/english/new-concept/book-2/mistakes"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 全册短语与句型 · 第49–74课","link":"/life/english/new-concept/book-2/phrases-part-03"},"next":{"text":"第二册：实践与进步 · 全册易错点","link":"/life/english/new-concept/book-2/mistakes"}},"headers":[],"relativePath":"life/english/new-concept/book-2/phrases-part-04.md","filePath":"life/english/new-concept/book-2/phrases-part-04.md"}'),a={name:"life/english/new-concept/book-2/phrases-part-04.md"};function i(t,e,r,h,p,c){return s(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="第二册-实践与进步-·-全册短语与句型-·-第75–96课" tabindex="-1">第二册：实践与进步 · 全册短语与句型 · 第75–96课 <a class="header-anchor" href="#第二册-实践与进步-·-全册短语与句型-·-第75–96课" aria-label="Permalink to &quot;第二册：实践与进步 · 全册短语与句型 · 第75–96课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/phrases">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><h2 id="lesson-75-·-不定式与目的" tabindex="-1">Lesson 75 · 不定式与目的 <a class="header-anchor" href="#lesson-75-·-不定式与目的" aria-label="Permalink to &quot;Lesson 75 · 不定式与目的 {#lesson-75-·-不定式与目的}&quot;">​</a></h2><ul><li>call for help — 呼救、请求援助</li><li>in need of — 需要，of 后接名词</li></ul><p><strong>句型示范：</strong> The hikers laid bright jackets on the rocks to attract attention.</p><p>laid 为 lay 的过去式，bright jackets 是宾语，to attract 为目的状语，执行者与 hikers 一致。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-075">进入本课</a></p><h2 id="lesson-76-·-间接引语与视角转换" tabindex="-1">Lesson 76 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-76-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 76 · 间接引语与视角转换 {#lesson-76-·-间接引语与视角转换}&quot;">​</a></h2><ul><li>fall for a story — 轻信一个故事</li><li>check the source — 核对来源，不等于只看标题</li></ul><p><strong>句型示范：</strong> The programme claimed that the trees could grow blue apples.</p><p>claimed 为报告动词，that 从句是被声称的内容；could 是从过去视角表达能力，句子不证明该能力真实。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-076">进入本课</a></p><h2 id="lesson-77-·-现在完成时与过去时间" tabindex="-1">Lesson 77 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-77-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 77 · 现在完成时与过去时间 {#lesson-77-·-现在完成时与过去时间}&quot;">​</a></h2><ul><li>recover from — 从伤病或困难中恢复</li><li>be able to — 能够，后接原形</li></ul><p><strong>句型示范：</strong> The injured bird has recovered enough to stand on both feet.</p><p>has recovered 为完成时，enough to stand 表达到某种程度，on both feet 说明动作状态。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-077">进入本课</a></p><h2 id="lesson-78-·-动名词与动词搭配" tabindex="-1">Lesson 78 · 动名词与动词搭配 <a class="header-anchor" href="#lesson-78-·-动名词与动词搭配" aria-label="Permalink to &quot;Lesson 78 · 动名词与动词搭配 {#lesson-78-·-动名词与动词搭配}&quot;">​</a></h2><ul><li>give up a habit — 放弃一个习惯</li><li>make an effort to — 努力做某事，后接原形</li></ul><p><strong>句型示范：</strong> Jon stopped buying cigarettes on his way to work.</p><p>stopped 为谓语，buying 作动名词宾语，on his way to work 是购买发生的情境。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-078">进入本课</a></p><h2 id="lesson-79-·-时间、原因与让步从句" tabindex="-1">Lesson 79 · 时间、原因与让步从句 <a class="header-anchor" href="#lesson-79-·-时间、原因与让步从句" aria-label="Permalink to &quot;Lesson 79 · 时间、原因与让步从句 {#lesson-79-·-时间、原因与让步从句}&quot;">​</a></h2><ul><li>despite the delay — 尽管延误，despite 后不加 of</li><li>look down at — 向下看某物</li></ul><p><strong>句型示范：</strong> Despite the delay, we enjoyed the view from the plane.</p><p>Despite the delay 是介词短语，主句 enjoyed 为过去式，from the plane 给出观察位置。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-079">进入本课</a></p><h2 id="lesson-80-·-被动语态与信息重点" tabindex="-1">Lesson 80 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-80-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 80 · 被动语态与信息重点 {#lesson-80-·-被动语态与信息重点}&quot;">​</a></h2><ul><li>be used for — 被用来，for 后接名词或动名词</li><li>on display — 在展出，不加冠词</li></ul><p><strong>句型示范：</strong> The exhibition hall was built from glass and steel.</p><p>was built 为一般过去被动，from glass and steel 说明建材；主语是展厅而非建造者。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-080">进入本课</a></p><h2 id="lesson-81-·-分词修饰与逻辑主语" tabindex="-1">Lesson 81 · 分词修饰与逻辑主语 <a class="header-anchor" href="#lesson-81-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;Lesson 81 · 分词修饰与逻辑主语 {#lesson-81-·-分词修饰与逻辑主语}&quot;">​</a></h2><ul><li>in disguise — 伪装着</li><li>draw somebody&#39;s attention — 引起某人注意</li></ul><p><strong>句型示范：</strong> Dressed as a cleaner, the prisoner walked towards the side gate.</p><p>Dressed 为过去分词状语，逻辑主语是 prisoner；walked 为主句谓语，towards 表方向。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-081">进入本课</a></p><h2 id="lesson-82-·-情态动词的意义与形式" tabindex="-1">Lesson 82 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-82-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 82 · 情态动词的意义与形式 {#lesson-82-·-情态动词的意义与形式}&quot;">​</a></h2><ul><li>turn out to be — 最后证明是</li><li>beyond doubt — 毫无疑问，需要充分证据</li></ul><p><strong>句型示范：</strong> The shape in the photograph might have been a large fish.</p><p>might have been 为对过去身份的推测，a large fish 为表语；might 表不确定，不是过去能力。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-082">进入本课</a></p><h2 id="lesson-83-·-将来表达与安排" tabindex="-1">Lesson 83 · 将来表达与安排 <a class="header-anchor" href="#lesson-83-·-将来表达与安排" aria-label="Permalink to &quot;Lesson 83 · 将来表达与安排 {#lesson-83-·-将来表达与安排}&quot;">​</a></h2><ul><li>vote for — 投票支持某人或方案</li><li>keep a promise — 履行承诺</li></ul><p><strong>句型示范：</strong> The candidate promised that the council would publish a plan by June.</p><p>promised 明确信息来源，would publish 是过去视角的将来，by June 表截止时间。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-083">进入本课</a></p><h2 id="lesson-84-·-将来进行时与过程" tabindex="-1">Lesson 84 · 将来进行时与过程 <a class="header-anchor" href="#lesson-84-·-将来进行时与过程" aria-label="Permalink to &quot;Lesson 84 · 将来进行时与过程 {#lesson-84-·-将来进行时与过程}&quot;">​</a></h2><ul><li>reach an agreement — 达成协议</li><li>go on strike — 开始罢工，strike 在此不用 a</li></ul><p><strong>句型示范：</strong> At ten tomorrow, the two sides will be discussing the revised offer.</p><p>will be discussing 为将来进行时，the two sides 是复数主语，revised 为过去分词定语。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-084">进入本课</a></p><h2 id="lesson-85-·-不定式与目的" tabindex="-1">Lesson 85 · 不定式与目的 <a class="header-anchor" href="#lesson-85-·-不定式与目的" aria-label="Permalink to &quot;Lesson 85 · 不定式与目的 {#lesson-85-·-不定式与目的}&quot;">​</a></h2><ul><li>gain confidence — 建立信心</li><li>learn at your own pace — 按自己的速度学习</li></ul><p><strong>句型示范：</strong> Ruth was nervous, but she was not too old to learn coding.</p><p>not too old to learn 否定年龄成为绝对障碍；to learn 为结果相关不定式，coding 是 learn 的宾语内容。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-085">进入本课</a></p><h2 id="lesson-86-·-分词修饰与逻辑主语" tabindex="-1">Lesson 86 · 分词修饰与逻辑主语 <a class="header-anchor" href="#lesson-86-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;Lesson 86 · 分词修饰与逻辑主语 {#lesson-86-·-分词修饰与逻辑主语}&quot;">​</a></h2><ul><li>lose control of — 失去对……的控制</li><li>slow down — 减速，可不接宾语</li></ul><p><strong>句型示范：</strong> Hearing a strange sound, the driver slowed down immediately.</p><p>Hearing 的执行者是 driver；slowed down 为主句谓语，immediately 是时间方式相关副词。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-086">进入本课</a></p><h2 id="lesson-87-·-间接引语与视角转换" tabindex="-1">Lesson 87 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-87-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 87 · 间接引语与视角转换 {#lesson-87-·-间接引语与视角转换}&quot;">​</a></h2><ul><li>account for — 解释某事或行踪</li><li>check against — 对照另一资料核查</li></ul><p><strong>句型示范：</strong> The officer asked where Daniel had been before eight.</p><p>asked 引出间接特殊疑问，where 从句按主语 Daniel 加 had been 排列；before eight 是核对时段。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-087">进入本课</a></p><h2 id="lesson-88-·-被动语态与信息重点" tabindex="-1">Lesson 88 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-88-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 88 · 被动语态与信息重点 {#lesson-88-·-被动语态与信息重点}&quot;">​</a></h2><ul><li>be trapped in — 被困在某处</li><li>keep in touch with — 与……保持联系</li></ul><p><strong>句型示范：</strong> Fresh air will be supplied through a narrow pipe.</p><p>will be supplied 是将来被动，through 引出通道，Fresh air 不可数。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-088">进入本课</a></p><h2 id="lesson-89-·-动词、宾语与补足语" tabindex="-1">Lesson 89 · 动词、宾语与补足语 <a class="header-anchor" href="#lesson-89-·-动词、宾语与补足语" aria-label="Permalink to &quot;Lesson 89 · 动词、宾语与补足语 {#lesson-89-·-动词、宾语与补足语}&quot;">​</a></h2><ul><li>a slip of the tongue — 口误，通常不是故意说谎</li><li>correct yourself — 自我纠正，用反身代词</li></ul><p><strong>句型示范：</strong> I meant to say Thursday, but I accidentally said Tuesday.</p><p>meant to say 表意图，said 是实际行为，but 标出意图与结果的不一致。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-089">进入本课</a></p><h2 id="lesson-90-·-分词修饰与逻辑主语" tabindex="-1">Lesson 90 · 分词修饰与逻辑主语 <a class="header-anchor" href="#lesson-90-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;Lesson 90 · 分词修饰与逻辑主语 {#lesson-90-·-分词修饰与逻辑主语}&quot;">​</a></h2><ul><li>run out of — 用完，主语通常是使用者</li><li>be used for — 用于，for 后可接名词或 -ing</li></ul><p><strong>句型示范：</strong> The potatoes fried this morning were used for supper.</p><p>fried this morning 是过去分词后置定语，were used 才是主句谓语，主语 potatoes 为复数。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-090">进入本课</a></p><h2 id="lesson-91-·-过去进行时与叙事背景" tabindex="-1">Lesson 91 · 过去进行时与叙事背景 <a class="header-anchor" href="#lesson-91-·-过去进行时与叙事背景" aria-label="Permalink to &quot;Lesson 91 · 过去进行时与叙事背景 {#lesson-91-·-过去进行时与叙事背景}&quot;">​</a></h2><ul><li>at a height of — 在……高度，后接数值单位</li><li>come down — 下降，也可表示价格下降，需看语境</li></ul><p><strong>句型示范：</strong> We were drifting over the fields when the pilot noticed a clear landing area.</p><p>were drifting 为背景，when 引出 noticed；a clear landing area 首次引入新地点。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-091">进入本课</a></p><h2 id="lesson-92-·-间接引语与视角转换" tabindex="-1">Lesson 92 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-92-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 92 · 间接引语与视角转换 {#lesson-92-·-间接引语与视角转换}&quot;">​</a></h2><ul><li>take offence — 感到被冒犯</li><li>in a calm tone — 用平静的语气</li></ul><p><strong>句型示范：</strong> I do not think the receptionist meant to be rude.</p><p>do not think 否定判断，meant to be 表意图；说话者评价的是意图，而不是否认语气可能让人不舒服。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-092">进入本课</a></p><h2 id="lesson-93-·-定语从句与指代" tabindex="-1">Lesson 93 · 定语从句与指代 <a class="header-anchor" href="#lesson-93-·-定语从句与指代" aria-label="Permalink to &quot;Lesson 93 · 定语从句与指代 {#lesson-93-·-定语从句与指代}&quot;">​</a></h2><ul><li>a gift from — 来自……的礼物</li><li>a symbol of — ……的象征，不等于实际包含该事物</li></ul><p><strong>句型示范：</strong> The statue, which was donated by local artists, stands beside the library.</p><p>The statue 为主语，stands 为主句谓语；逗号内 which was donated 是非限制性定语从句，which 指 statue。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-093">进入本课</a></p><h2 id="lesson-94-·-一般现在时与习惯" tabindex="-1">Lesson 94 · 一般现在时与习惯 <a class="header-anchor" href="#lesson-94-·-一般现在时与习惯" aria-label="Permalink to &quot;Lesson 94 · 一般现在时与习惯 {#lesson-94-·-一般现在时与习惯}&quot;">​</a></h2><ul><li>learn to do — 学会做某事</li><li>under supervision — 在监督照看下，通常不用 a</li></ul><p><strong>句型示范：</strong> The children practise floating before they learn to swim across the pool.</p><p>practise 后接动名词 floating，learn 后接 to swim；before 引出学习顺序，children 为复数。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-094">进入本课</a></p><h2 id="lesson-95-·-非真实条件句" tabindex="-1">Lesson 95 · 非真实条件句 <a class="header-anchor" href="#lesson-95-·-非真实条件句" aria-label="Permalink to &quot;Lesson 95 · 非真实条件句 {#lesson-95-·-非真实条件句}&quot;">​</a></h2><ul><li>what if — 如果……会怎样，用于提出设想</li><li>come true — 梦想等变为现实，不用被动</li></ul><p><strong>句型示范：</strong> If people could store sunlight in a pocket, winter evenings would look different.</p><p>could store 表非真实能力假设，would look 表设想结果；sunlight 不可数，in a pocket 为幻想中的容器。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-095">进入本课</a></p><h2 id="lesson-96-·-被动语态与信息重点" tabindex="-1">Lesson 96 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-96-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 96 · 被动语态与信息重点 {#lesson-96-·-被动语态与信息重点}&quot;">​</a></h2><ul><li>honour the memory of — 纪念某人</li><li>according to tradition — 按照传统，标明文化来源</li></ul><p><strong>句型示范：</strong> The lanterns are placed by the river to honour family ancestors.</p><p>are placed 是一般现在时被动，概括仪式做法；by the river 是地点而非执行者，to honour 表目的。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-096">进入本课</a></p>',113)])])}const g=o(a,[["render",i]]);export{u as __pageData,g as default};
